{
  "iteration": 1,
  "pcvs": [
    {
      "name": "request_count",
      "expression": "self.llm_engine.get_num_unfinished_requests()",
      "rationale": "Measures batch size, which drives per-request inference, output processing, and sorting."
    },
    {
      "name": "decode_rounds_proxy",
      "expression": "min(4, 2 * self.llm_engine.get_num_unfinished_requests() - 1)",
      "rationale": "Matches the maximum requested generation length in each supplied batch, approximating engine-step overhead."
    },
    {
      "name": "long_prompt_requests",
      "expression": "self.llm_engine.get_num_unfinished_requests() if use_tqdm >= 4 else 0",
      "rationale": "The supplied workload switches to long shared-prefix prompts at this entry-state threshold, changing prefill and penalty-processing work."
    },
    {
      "name": "initial_batch",
      "expression": "int(use_tqdm == 0)",
      "rationale": "Identifies the initial execution, which may incur lazy initialization and also omits progress reporting."
    }
  ],
  "hypothesis": "Instruction count combines per-request work, engine-step overhead, additional long-prompt processing, and initial-execution overhead. The workload-specific proxies are cheap expressions of entry state."
}
